async function resetTestProgress(moduleId:string|null=null){
 if(!isTestLearner||!user||testResetBusy)return;
 const targetModule=moduleId?mods.find(m=>m.id===moduleId):null;
 if(moduleId&&!targetModule)return;
 const scope=targetModule?"Module "+targetModule.order_index+" — "+targetModule.title:"ALL eight modules";
 if(!window.confirm("Reset "+scope+" for the test Ian account?\n\nThis deletes the selected test quiz results, assignment submissions and any associated reviews. This cannot be undone.\n\nThe real Ian account and Brenda's workspace are unaffected."))return;
 setTestResetBusy(true);
 try{
  const {error}=await db.rpc("aspectus_reset_test_progress",{p_module_id:moduleId});
  if(error)throw error;
  // The embedded lesson stores its stage and answers locally; clear only this test user's state.
  const key="cheche-onboarding-aspectus-ian-v1-profile-"+user.id.toLowerCase();
  try{
   if(!moduleId){window.localStorage.removeItem(key)}
   else{
    const raw=window.localStorage.getItem(key);
    if(raw){
     const state=JSON.parse(raw);
     if(state&&typeof state==="object"){
      if(state.mods&&typeof state.mods==="object")delete state.mods["m"+targetModule?.order_index];
      if(targetModule?.order_index===1){state.baseline=null;delete state._bl;state._blStep=0;}
      window.localStorage.setItem(key,JSON.stringify(state));
     }
    }
   }
  }catch{window.localStorage.removeItem(key)}
  setActiveLesson(false);
  setSelected("");
  await refresh();
  setScreen("learning");
  setMsg(targetModule?"Test Module "+targetModule.order_index+" has been reset. Open it to start again.":"Test progress reset. All eight modules are ready to start again.");
 }catch(error){setMsg("Could not reset test progress: "+(error instanceof Error?error.message:String(error)));}
 finally{setTestResetBusy(false)}
}
async function authorizeNext(learnerId:string,moduleId:string){if(!user||!manager||overrideBusy)return;const reason=(overrideReason[moduleId]||"").trim();if(reason.length<10){setMsg("Please enter a clear reason (at least 10 characters).");return}setOverrideBusy(true);const {error}=await db.from("aspectus_module_overrides").insert({org_id:user.org_id,learner_id:learnerId,module_id:moduleId,authorized_by:user.id,reason});if(error)setMsg("Could not authorize progression: "+error.message);else{setMsg("Next module unlocked for learner. This does not count as a passed quiz or approved assignment.");setOverrideReason(v=>({...v,[moduleId]:""}));await refresh()}setOverrideBusy(false)}
